function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function modelProfile(kind){
  kind=String(kind||'通用对话');
  if(kind.indexOf('代码')>=0) return {model:'代码增强型', maxTokens:'8K', note:'优先使用沙箱执行验证代码'};
  if(kind.indexOf('长文')>=0) return {model:'长上下文型', maxTokens:'128K', note:'注意上下文窗口与摘要压缩'};
  if(kind.indexOf('多模态')>=0) return {model:'多模态型', maxTokens:'32K', note:'图像输入建议压缩后上传'};
  return {model:'通用对话型', maxTokens:'16K', note:'默认开启流式输出'};
}
function tempProfile(t){
  t=String(t||'平衡');
  if(t.indexOf('精确')>=0) return {temp:'0.2', when:'结构化抽取、固定格式输出'};
  if(t.indexOf('创意')>=0) return {temp:'1.0', when:'头脑风暴、文案发散'};
  return {temp:'0.7', when:'日常对话与综合任务'};
}
function memoryKey(m){
  m=String(m||'');
  if(m.indexOf('长期')>=0) return 'long-term-rag';
  if(m.indexOf('短期')>=0) return 'session';
  return 'none';
}
function buildAgentSpec(o){
  o=o||{};
  var name=String(o.name||'').trim()||'UnnamedAgent';
  var role=String(o.role||'').trim()||'（待补充角色定位）';
  var kind=String(o.kind||'通用对话');
  var temp=String(o.temp||'平衡');
  var tools=splitLines(o.tools);
  var memory=String(o.memory||'短期记忆');
  var constraints=splitLines(o.constraints);
  if(!constraints.length) constraints=['回答须基于检索到的事实，不得编造','涉及敏感操作需向用户二次确认'];
  var mp=modelProfile(kind), tp=tempProfile(temp), mk2=memoryKey(memory);
  var memDesc = mk2==='long-term-rag' ? '会话内上下文 + 向量库长期记忆（RAG 检索）' : (mk2==='session' ? '仅会话内上下文，会话结束即遗忘' : '无记忆，单轮请求独立应答');
  var lines=[];
  lines.push('# 智能体规格书：'+name);
  lines.push('');
  lines.push('## 一、基本信息');
  lines.push('- 名称：'+name);
  lines.push('- 角色定位：'+role);
  lines.push('- 模型类型：'+mp.model+'（'+mp.note+'）');
  lines.push('- 温度：'+tp.temp+'（适用：'+tp.when+'）');
  lines.push('- 最大输出：'+mp.maxTokens);
  lines.push('');
  lines.push('## 二、工具能力');
  if(tools.length){ tools.forEach(function(t,i){ lines.push((i+1)+'. '+t); }); }
  else { lines.push('（无外部工具，纯对话能力）'); }
  lines.push('');
  lines.push('## 三、记忆策略');
  lines.push('- '+memDesc);
  lines.push('');
  lines.push('## 四、约束与安全');
  constraints.forEach(function(c){ lines.push('- '+c); });
  lines.push('');
  lines.push('## 五、YAML 快照');
  lines.push('```yaml');
  lines.push('agent:');
  lines.push('  name: "'+name+'"');
  lines.push('  model: "'+mp.model+'"');
  lines.push('  temperature: '+tp.temp);
  lines.push('  tools: '+tools.length);
  lines.push('  memory: "'+mk2+'"');
  lines.push('```');
  return {title:name+' 智能体规格书', toolCount:tools.length, temperature:tp.temp,
          memory:mk2, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, modelProfile:modelProfile, tempProfile:tempProfile, memoryKey:memoryKey, buildAgentSpec:buildAgentSpec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AiAgentSpecForgePure = EXPORTS; }
